    let quiet = 0, last = 0; LL.forEach((l) => { const m = by.get(l.i); const snd = (m?.events || []).some((e) => e.sound && !/тиш/i.test(e.sound)); if (snd) last = l.t1; else if (l.t1 - last > 5 && !(m?.events || []).some((e) => /тиш/i.test(e.sound || ""))) quiet++; });
